"""Local-only visual theme and short, keyboard-accessible control help."""

STYLE = '''
:root{color-scheme:light;--ink:#15243b;--muted:#53647d;--line:#dce4ef;--accent:#4058da}
body{background:radial-gradient(ellipse at top right,#e9efff,transparent 55%),#f5f7fb;color:var(--ink);font-family:Inter,Segoe UI,system-ui,sans-serif}
main{max-width:1240px;margin:40px auto;padding:0 32px 50px}h1{font-size:clamp(32px,4vw,52px);letter-spacing:-2px;line-height:1.1;margin:32px 0 18px}h2{letter-spacing:-.7px;font-size:27px}h3{letter-spacing:-.3px}p,li,span{color:var(--muted)}p{max-width:1000px}.brand{color:var(--accent);font-weight:750;letter-spacing:2px}a{color:#354dc4;text-underline-offset:3px}
button,.preview-tab{background:#4058da;color:white;border:1px solid transparent;border-radius:11px;padding:12px 18px;box-shadow:0 3px 8px #263d7910;font:650 14px Segoe UI,system-ui;transition:background .15s,box-shadow .15s}button:hover{background:#3046bc;box-shadow:0 4px 14px #263d7920}button:disabled{background:#d9dfeb;color:#61718a;opacity:1;cursor:not-allowed;box-shadow:none}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #687cf1;outline-offset:3px}
nav{gap:10px}nav>a:first-child{margin-right:auto;font-size:14px;font-weight:650}#json-export,#svg-export,#ai-status,#ai-disconnect,#ai-clear{background:white;color:#354dc4;border-color:#d2dbed;box-shadow:none}#json-export:hover,#svg-export:hover,#ai-status:hover,#ai-disconnect:hover,#ai-clear:hover{background:#edf1ff}
[role=tablist]{background:#f5f7fbeb;backdrop-filter:blur(16px);border:1px solid var(--line);border-radius:15px;padding:7px;gap:5px;margin-top:24px;box-shadow:0 3px 10px #293f6510;top:10px}[role=tab]{font:650 13px Segoe UI,system-ui;border:0;background:transparent;color:#53647d;padding:11px 15px;border-radius:9px;box-shadow:none}[role=tab]:hover{background:#e8edf8;color:#283f9d}[role=tab][aria-selected=true]{background:white;color:#354dc4;box-shadow:0 2px 8px #23375618}
.cards{margin:26px 0;gap:14px}.cards article{flex:1;min-width:140px;background:white;border:1px solid var(--line);border-radius:15px;box-shadow:0 5px 16px #23375605;padding:22px}.cards strong{font-size:32px;color:#23375b;letter-spacing:-1px}.cards span{font-size:13px;text-transform:uppercase;letter-spacing:.8px}
[role=tabpanel],#home-about,#home-faq{background:white;border:1px solid var(--line);border-radius:18px;padding:28px;margin-top:24px;box-shadow:0 8px 30px #23375606}[role=tabpanel]>h2:first-child{margin-top:0}.explanation,.workflow-steps li,#map-details{background:#f5f7fc;border:1px solid var(--line);border-radius:13px}.explanation b{color:#23375b}.assessment{color:#3e55b8}.workflow-steps li{border-left:4px solid #6177e8}.workflow-steps li+li:before{color:#6177e8}
input[type=search],input[type=file],textarea,select{background:#f7f9fd;color:var(--ink);border:1px solid #cbd6e7;border-radius:10px;padding:12px;font:14px Segoe UI,system-ui}select{max-width:100%}input[type=file]::file-selector-button{background:#e8edff;color:#354dc4;border:0;padding:10px 14px;border-radius:7px;margin-right:12px;font-weight:650}form{background:white;border:1px dashed #b9c8e2;padding:26px;border-radius:16px;margin:24px 0}label{font-size:14px;color:#35465f}input[type=checkbox]{accent-color:#4058da}code,pre{background:#edf1f8;color:#35465f;border-radius:5px}code{padding:2px 5px}td,th{border-color:var(--line)}th{color:#4a5e7b;background:#f5f7fb}tr:target{background:#e5ebff}details{border-bottom:1px solid #e4eaf3;padding:8px 0}summary{font-weight:650;color:#35465f;cursor:pointer}.ai-findings{background:#f8faff;border-color:var(--line);border-radius:10px}#ai-account,#ai-progress,#status{font-size:14px;color:#40547a}.map-viewport{background:#162130}svg span{color:inherit}
#control-help{position:fixed;z-index:1000;max-width:260px;background:#17283f;color:white;padding:9px 12px;border-radius:8px;box-shadow:0 5px 20px #17283f30;font:13px/1.45 Segoe UI,system-ui;pointer-events:none}
@media(max-width:650px){main{padding:0 16px;margin:24px auto}[role=tabpanel]{padding:19px}.cards article{min-width:90px;padding:15px}[role=tab]{padding:10px 11px;font-size:12px}nav>a:first-child{width:100%}h1{letter-spacing:-1px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}@media print{body{background:white}[role=tabpanel]{box-shadow:none;border:0}#control-help{display:none!important}}
'''

SCRIPT = '''(()=>{
const tips={'json-export':'Save structured findings for tools or comparison.','html-export':'Save a readable report for offline review.','svg-export':'Save the current feature diagram as an image.','tab-behavior':'Learn what Reversium can help you achieve.','tab-finish':'Save a report and plan your next checks.','tab-software':'Read explanations of the uploaded software.','tab-architecture':'Explore components and feature connections.','tab-evidence':'Inspect findings and source locations.','tab-coverage':'See what was inspected and what remains unknown.','tab-assistant':'Ask AI about evidence you choose to share.','tab-faq':'Find quick answers and setup guidance.','ai-connect':'Prepare sign-in with your ChatGPT account.','ai-status':'Check sign-in and available account models.','ai-disconnect':'Remove account tokens from this local session.','ai-prepare':'Preview the question and selected findings.','ai-send':'Send only the approved preview to OpenAI.','ai-clear':'Clear your local question, selection and answer.'};
const byText={'Continue to ZIP':'Choose the software package for your goal.','Analyze ZIP locally':'Inspect the selected ZIP without running its code.','Back to Start':'Return to your goal selection.','Explore feature connections':'See supported paths between components.','Check gaps and limitations':'Review what this analysis cannot establish.','Continue to save & next steps':'Save a report and plan verification.','Review remaining gaps':'Check unresolved setup and coverage questions.','Optional: ask AI about selected evidence':'Choose evidence to discuss with your AI account.','Choose ZIP archive':'Choose the software ZIP to inspect locally.','Analyze archive':'Inspect the selected ZIP on your computer.','About':'Learn what Reversium can help you achieve.','FAQ':'Find quick answers and setup guidance.','Analyze another ZIP':'Return to the archive upload screen.','Open OpenAI sign-in':'Open the provider’s account sign-in page.'};
let active=null;const tip=document.createElement('div');tip.id='control-help';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);
function hide(){tip.hidden=true;if(active){const ids=(active.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!=='control-help');if(ids.length)active.setAttribute('aria-describedby',ids.join(' '));else active.removeAttribute('aria-describedby')}active=null}
function show(target){const el=target.closest?.('button,input[type=file],[role=tab],summary,a.preview-tab,nav a,[role=button]');if(!el)return;hide();const name=(el.textContent||el.getAttribute('aria-label')||'').trim();const text=tips[el.id]||byText[name]||(el.matches('summary')?'Expand or collapse this explanation.':el.closest('svg')?'Inspect this source reference and its evidence.':el.getAttribute('role')==='tab'?'Open this report section.':'Open this item.');active=el;tip.textContent=text;tip.hidden=false;el.setAttribute('aria-describedby',((el.getAttribute('aria-describedby')||'')+' control-help').trim());const r=el.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(r.left,window.innerWidth-tip.offsetWidth-8))+'px';tip.style.top=(r.bottom+tip.offsetHeight+12>window.innerHeight?Math.max(8,r.top-tip.offsetHeight-8):r.bottom+8)+'px'}
document.addEventListener('pointerover',e=>show(e.target));document.addEventListener('pointerout',e=>{if(active&&!active.contains(e.relatedTarget))hide()});document.addEventListener('focusin',e=>show(e.target));document.addEventListener('focusout',hide);document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});document.addEventListener('scroll',hide,true);window.addEventListener('resize',hide);
})();'''

STYLE += 'fieldset{border:0;padding:0;margin:0;width:100%}legend{font-weight:700;margin-bottom:14px}.goal-choice{display:block;background:#f7f9fd;border:1px solid #dce4ef;padding:18px;border-radius:12px;margin-bottom:12px;cursor:pointer}.goal-choice:has(input:checked){border-color:#4058da;background:#edf1ff}.goal-choice input{margin-right:8px}.sample-notice{background:#fff4d9;border:1px solid #dfc37c;padding:14px;border-radius:10px;color:#735414}#start-screen,#upload-screen{max-width:900px}#start-about,#start-faq{background:white;padding:24px;border-radius:16px}'

STYLE += '.action-plan{padding-left:24px;max-width:900px}.action-plan>li{padding:14px 0;border-bottom:1px solid #dce4ef}.action-plan p{margin:7px 0}.action-plan b{color:#253c61}.owner-caution{background:#fff7e6;border:1px solid #ead7a7;padding:18px;border-radius:12px}.owner-caution h3{margin-top:0}'
